# Edit this: what you want to read about.
INTERESTS = "developer tools, Python, AI, privacy, productivity"

import re
import xml.etree.ElementTree as ET


def tag(el):
    return el.tag.rsplit("}", 1)[-1]


def main(input_data):
    root = ET.fromstring(input_data["body"])
    entries = [e for e in root.iter() if tag(e) in ("item", "entry")][:20]
    lines = []
    for e in entries:
        parts = {tag(c): c for c in e}
        title = (parts["title"].text or "").strip() if "title" in parts else ""
        link = ""
        if "link" in parts:
            link = (parts["link"].text or parts["link"].attrib.get("href", "")).strip()
        blurb = ""
        for key in ("description", "summary"):
            if key in parts and parts[key].text:
                blurb = re.sub(r"<[^>]+>", " ", parts[key].text)
                blurb = re.sub(r"\s+", " ", blurb).strip()[:200]
        lines.append("- %s (%s) %s" % (title, link, blurb))
    if not lines:
        raise ValueError("No entries found. Is this an RSS or Atom feed?")
    return {"interests": INTERESTS, "list": "\n".join(lines), "count": len(lines)}

